import{createStudy,canvasSurface,seededRandom,clamp,lerp,downloadCanvas}from'./core.js';
const study=createStudy({id:16,title:'Small Giants',category:'Micro / Response',accent:'#4841ff',background:'#f0ede5',foreground:'#181a25'});
const canvas=document.querySelector('#giant-field'),surface=canvasSurface(canvas),random=seededRandom(16),dots=Array.from({length:130},()=>({x:random(),y:random(),r:.7+random()*1.4}));
const press=document.querySelector('#spring-press'),toggle=document.querySelector('#giant-switch'),zone=document.querySelector('#magnet-zone'),magnet=document.querySelector('#magnet-button'),dial=document.querySelector('#giant-dial');
let count=0,pressed=false,on=false,pointer={x:.5,y:.5},magnetic={x:0,y:0,tx:0,ty:0},pressScale=1,orbX=0,dialAngle=45,bursts=[];
function render({dt,time}){const smooth=dt?1-Math.exp(-dt*15):study.running()?0:1;pressScale=lerp(pressScale,pressed?.91:1,smooth);press.style.transform=`translateY(${(1-pressScale)*90}px) scale(${pressScale})`;const travel=toggle.clientWidth-toggle.querySelector('span').clientWidth-10;orbX=lerp(orbX,on?travel:0,smooth);toggle.querySelector('span').style.transform=`translateX(${orbX}px)`;magnetic.x=lerp(magnetic.x,magnetic.tx,smooth);magnetic.y=lerp(magnetic.y,magnetic.ty,smooth);magnet.style.transform=`translate(${magnetic.x}px,${magnetic.y}px) rotate(${magnetic.x*.6}deg)`;dialAngle=lerp(dialAngle,+dial.value,smooth);document.querySelector('#dial-flower').style.transform=`rotate(${dialAngle}deg)`;const{ctx,width:w,height:h}=surface;ctx.fillStyle='#f0ede5';ctx.fillRect(0,0,w,h);const cx=pointer.x*w,cy=pointer.y*h;for(const d of dots){const x=d.x*w,y=d.y*h,dist=Math.hypot(x-cx,y-cy),force=Math.max(0,1-dist/115),dx=(x-cx)*force*.35,dy=(y-cy)*force*.35;ctx.beginPath();ctx.arc(x+dx,y+dy,d.r+force*3,0,Math.PI*2);ctx.fillStyle=force>.3?'#4841ff':'#b4b3c0';ctx.fill()}ctx.strokeStyle='#4841ff';ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,26+Math.sin(time*2)*2,0,Math.PI*2);ctx.stroke();for(const b of bursts){if(dt)b.age+=dt;const progress=clamp(b.age/.65);b.element.style.transform=`translate(${Math.cos(b.angle)*progress*110}px,${Math.sin(b.angle)*progress*100+progress*progress*25}px) rotate(${progress*220}deg)`;b.element.style.opacity=1-progress}bursts=bursts.filter(b=>{if(b.age>.65){b.element.remove();return false}return true})}
function burst(){count++;document.querySelector('#press-count').textContent=String(count).padStart(3,'0');if(study.running())for(let i=0;i<14;i++){const element=document.createElement('i');document.querySelector('#press-burst').append(element);bursts.push({element,angle:i/14*Math.PI*2,age:0})}study.invalidate()}
press.addEventListener('pointerdown',()=>{pressed=true;study.invalidate()});for(const e of['pointerup','pointercancel','pointerleave','blur'])press.addEventListener(e,()=>{pressed=false;study.invalidate()});press.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){pressed=true;study.invalidate()}});press.addEventListener('keyup',()=>{pressed=false;study.invalidate()});press.addEventListener('click',burst);
toggle.addEventListener('click',()=>{on=!on;toggle.setAttribute('aria-checked',String(on));toggle.closest('article').classList.toggle('is-on',on);document.querySelector('#switch-word').textContent=on?'IN MOTION.':'POSSIBLE.';study.invalidate()});zone.addEventListener('pointermove',e=>{const r=zone.getBoundingClientRect();magnetic.tx=(e.clientX-r.left-r.width/2)*.22;magnetic.ty=(e.clientY-r.top-r.height/2)*.22;study.invalidate()});zone.addEventListener('pointerleave',()=>{magnetic.tx=magnetic.ty=0;study.invalidate()});magnet.addEventListener('click',()=>{pointer={x:random(),y:random()};study.notify('A small impulse. A new response.');study.invalidate()});dial.addEventListener('input',()=>{document.querySelector('#dial-value').textContent=dial.value+'°';study.invalidate()});canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};study.invalidate()});study.onFrame(render);study.onResize(()=>surface.resize());study.onMotion(run=>{if(!run){bursts.forEach(b=>b.element.remove());bursts=[]}});study.setReset(()=>{bursts.forEach(b=>b.element.remove());bursts=[];count=0;pressed=false;on=false;pointer={x:.5,y:.5};magnetic.tx=magnetic.ty=0;dial.value=45;document.querySelector('#dial-value').textContent='45°';document.querySelector('#press-count').textContent='000';toggle.setAttribute('aria-checked','false');toggle.closest('article').classList.remove('is-on');document.querySelector('#switch-word').textContent='POSSIBLE.'});study.setExport(()=>downloadCanvas(canvas,'sub-small-giants-field.png'));study.cleanup(()=>surface.dispose());
